// apply-dark-mode.js
// Run this from inside the `frontend` folder: node apply-dark-mode.js
// It writes/overwrites the files below with dark-mode-ready versions, then you can delete this script.
const fs = require('fs');
const path = require('path');

const files = {
  "tailwind.config.js": "",
  "src/store/themeStore.ts": "",
  "src/index.css": "",
  "src/components/Header.tsx": "",
  "src/components/Sidebar.tsx": "",
  "src/components/Modal.tsx": "",
  "src/components/DataTable.tsx": "",
  "src/components/StatCard.tsx": "",
  "src/components/ProtectedRoute.tsx": "",
  "src/pages/Login.tsx": "",
  "src/components/ProductCard.tsx": "",
  "src/components/Cart.tsx": "",
  "src/components/NumericKeypad.tsx": "",
  "src/components/PaymentModal.tsx": "",
  "src/pages/POS.tsx": "",
};

for (const [relPath, b64] of Object.entries(files)) {
  const fullPath = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
  console.log('Wrote', relPath);
}
console.log('Done. ' + Object.keys(files).length + ' files written.');